DECLARE
    l_base_url CONSTANT VARCHAR2(4000) :=
        '#PEAKGEAR_MEDALLION.v_pg_aicat_catalog_url';

    l_client_secret CONSTANT VARCHAR2(4000) :=
        '#PEAKGEAR_MEDALLION.v_pg_password';

    l_auth_url CONSTANT VARCHAR2(4000) :=
        l_base_url || '/v1/auth/token';

    l_delete_url CONSTANT VARCHAR2(4000) :=
        l_base_url
        || '/v1/namespaces/silver/tables/ailh_enriched_sales';

    l_request        UTL_HTTP.REQ;
    l_response       UTL_HTTP.RESP;
    l_chunk          VARCHAR2(32767);
    l_auth_body      VARCHAR2(32767);
    l_request_body   VARCHAR2(32767);
    l_token          VARCHAR2(32767);
    l_status         NUMBER;
BEGIN
    ------------------------------------------------------------------
    -- Request AI Catalog access token
    ------------------------------------------------------------------
    l_request_body :=
        'grant_type=client_credentials'
        || '&client_id=' || UTL_URL.ESCAPE('PG')
        || '&client_secret=' || UTL_URL.ESCAPE(l_client_secret)
        || '&scope=PRINCIPAL_ROLE%3AALL';

    l_request := UTL_HTTP.BEGIN_REQUEST(
        l_auth_url,
        'POST',
        'HTTP/1.1'
    );

    UTL_HTTP.SET_HEADER(
        l_request,
        'Content-Type',
        'application/x-www-form-urlencoded'
    );

    UTL_HTTP.SET_HEADER(
        l_request,
        'Content-Length',
        LENGTH(l_request_body)
    );

    UTL_HTTP.WRITE_TEXT(
        l_request,
        l_request_body
    );

    l_response := UTL_HTTP.GET_RESPONSE(l_request);

    BEGIN
        LOOP
            UTL_HTTP.READ_TEXT(
                l_response,
                l_chunk,
                32767
            );

            l_auth_body := l_auth_body || l_chunk;
        END LOOP;
    EXCEPTION
        WHEN UTL_HTTP.END_OF_BODY THEN
            UTL_HTTP.END_RESPONSE(l_response);
    END;

    l_token := JSON_VALUE(
        l_auth_body,
        '$.access_token'
    );

    IF l_token IS NULL THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            'Unable to obtain AI Catalog access token.'
        );
    END IF;

    ------------------------------------------------------------------
    -- Delete Silver Iceberg table
    ------------------------------------------------------------------
    l_request := UTL_HTTP.BEGIN_REQUEST(
        l_delete_url,
        'DELETE',
        'HTTP/1.1'
    );

    UTL_HTTP.SET_HEADER(
        l_request,
        'Authorization',
        'Bearer ' || l_token
    );

    l_response := UTL_HTTP.GET_RESPONSE(l_request);
    l_status := l_response.STATUS_CODE;

    DBMS_OUTPUT.PUT_LINE(
        'DELETE silver/ailh_enriched_sales - HTTP status: '
        || l_status
    );

    UTL_HTTP.END_RESPONSE(l_response);

    IF l_status NOT IN (200, 202, 204, 404) THEN
        RAISE_APPLICATION_ERROR(
            -20002,
            'Failed to delete silver/ailh_enriched_sales. HTTP status: '
            || l_status
    );
    END IF;
END;
